add_action(
    'wp_ajax_upload_place_photo',
    'upload_place_photo'
);

function upload_place_photo()
{
    if (!is_user_logged_in()) {
        wp_send_json_error('Login required');
    }

    $place_id =
        sanitize_text_field(
            $_POST['place_id'] ?? ''
        );

    if (!$place_id) {
        wp_send_json_error('Place ID missing');
    }

    require_once ABSPATH .
        'wp-admin/includes/file.php';

    require_once ABSPATH .
        'wp-admin/includes/media.php';

    require_once ABSPATH .
        'wp-admin/includes/image.php';

    $attachment_id =
        media_handle_upload(
            'photo',
            0
        );

    if (is_wp_error($attachment_id)) {

        wp_send_json_error(
            $attachment_id->get_error_message()
        );
    }

    update_post_meta(
        $attachment_id,
        'place_id',
        $place_id
    );

    wp_send_json_success([
        'id' => $attachment_id,
        'url' => wp_get_attachment_url(
            $attachment_id
        )
    ]);
}
add_action(
    'wp_ajax_get_place_uploads',
    'get_place_uploads'
);
function get_place_uploads()
{
    $place_id =
        sanitize_text_field(
            $_GET['place_id'] ?? ''
        );

    $photos = get_posts([
        'post_type'      => 'attachment',
        'post_status'    => 'inherit',
        'posts_per_page' => -1,
        'meta_key'       => 'place_id',
        'meta_value'     => $place_id
    ]);

    $data = [];

    foreach ($photos as $photo) {

        $data[] = [
            'id'  => $photo->ID,
            'url' => wp_get_attachment_url(
                $photo->ID
            )
        ];
    }

    wp_send_json_success($data);
}

// upload Video
add_action(
    'wp_ajax_get_place_uploads_videos',
    'get_place_uploads_videos'
);

add_action(
    'wp_ajax_nopriv_get_place_uploads_videos',
    'get_place_uploads_videos'
);

function get_place_uploads_videos()
{
    $place_id = isset($_GET['place_id'])
        ? sanitize_text_field(wp_unslash($_GET['place_id']))
        : '';

    if (empty($place_id)) {
        wp_send_json_error([
            'message' => 'Missing place_id'
        ], 400);
    }

    $videos = get_posts([
        'post_type'      => 'attachment',
        'post_status'    => 'inherit',
        'posts_per_page' => -1,
        'post_mime_type' => 'video',
        'meta_key'       => 'place_id',
        'meta_value'     => $place_id,
    ]);

    $data = [];

    foreach ($videos as $video) {
        $url = wp_get_attachment_url($video->ID);

        if (!$url) {
            continue;
        }

        $data[] = [
            'id'        => $video->ID,
            'url'       => $url,
            'mime_type' => get_post_mime_type($video->ID),
        ];
    }

    wp_send_json_success($data);
}

// Search GEMINI
add_action(
    'wp_ajax_pt_ai_search',
    'pt_ai_search'
);

add_action(
    'wp_ajax_nopriv_pt_ai_search',
    'pt_ai_search'
);


function pt_ai_search()
{

    /*
     * =====================================================
     * 1. GET SEARCH QUERY
     * =====================================================
     */

    $query = isset($_POST['query'])
        ? sanitize_text_field(
            wp_unslash($_POST['query'])
        )
        : '';


    if ($query === '') {

        wp_send_json_error([
            'message' => 'Search content is empty.'
        ], 400);
    }


    /*
     * =====================================================
     * 2. GEMINI API KEY
     * =====================================================
     *
     * TEST ONLY
     */

    $api_key = 'AQ.Ab8RN6KpzRnB1gj1TrD7TCrKWQdb4QfmTzNzvI8qQtMk5vN2ZA';


    if (empty($api_key)) {

        wp_send_json_error([
            'message' => 'Gemini API key is empty.'
        ], 500);
    }


    /*
     * =====================================================
     * 3. PROMPT
     * =====================================================
     */

    $prompt = <<<PROMPT
You are a general AI search assistant.

Search and understand the user's entire input.

The user may ask about ANYTHING, including:
- places
- businesses
- restaurants
- cafes
- hotels
- hospitals
- schools
- companies
- people
- products
- services
- prices
- news
- events
- travel
- geography
- technology
- general knowledge
- current information
- or any other topic.

Do not restrict the search to places or categories.

Use Google Search when current or factual web information is useful.

Answer the user's actual query directly.

Do not invent information.

Respond in Vietnamese when appropriate.

Keep the answer concise.

Return HTML only.

Allowed HTML:
<p>
<strong>
<ul>
<li>
<br>

Do not use Markdown.
Do not use <html>, <head>, or <body>.

User query:
{$query}
PROMPT;
    /*
     * =====================================================
     * 4. GEMINI REQUEST BODY
     * =====================================================
     */

    $body = [

        'contents' => [

            [

                'role' => 'user',

                'parts' => [

                    [
                        'text' => $prompt
                    ]

                ]

            ]

        ]

    ];


    /*
     * =====================================================
     * 5. GEMINI MODEL
     * =====================================================
     */

    $model = 'gemini-3.6-flash';


    /*
     * =====================================================
     * 6. GEMINI API URL
     * =====================================================
     */

    $url =
        'https://generativelanguage.googleapis.com/v1beta/models/'
        . $model
        . ':generateContent';


    /*
     * =====================================================
     * 7. CALL GEMINI
     * =====================================================
     */

    $response = wp_remote_post(

        $url,

        [

            'timeout' => 60,

            'headers' => [

                'Content-Type' => 'application/json',

                'x-goog-api-key' => $api_key

            ],

            'body' => wp_json_encode($body)

        ]

    );


    /*
     * =====================================================
     * 8. CONNECTION ERROR
     * =====================================================
     */

    if (is_wp_error($response)) {

        wp_send_json_error([

            'message' =>
            'Unable to connect to Gemini: '
                . $response->get_error_message()

        ], 500);
    }


    /*
     * =====================================================
     * 9. HTTP STATUS
     * =====================================================
     */

    $status =
        wp_remote_retrieve_response_code(
            $response
        );


    /*
     * =====================================================
     * 10. RESPONSE BODY
     * =====================================================
     */

    $raw_body =
        wp_remote_retrieve_body(
            $response
        );


    $response_body =
        json_decode(
            $raw_body,
            true
        );


    /*
     * =====================================================
     * 11. INVALID JSON
     * =====================================================
     */

    if (!is_array($response_body)) {

        wp_send_json_error([

            'message' =>
            'Invalid response from Gemini.'

        ], 502);
    }


    /*
     * =====================================================
     * 12. GEMINI API ERROR
     * =====================================================
     */

    if (
        $status < 200 ||
        $status >= 300
    ) {

        $error_message =
            $response_body['error']['message']
            ?? 'Gemini API error.';


        wp_send_json_error([

            'message' => $error_message

        ], $status ?: 500);
    }


    /*
     * =====================================================
     * 13. GET GEMINI TEXT
     * =====================================================
     */

    $text = '';


    if (
        isset(
            $response_body['candidates'][0]['content']['parts']
        )
        &&
        is_array(
            $response_body['candidates'][0]['content']['parts']
        )
    ) {

        foreach (
            $response_body['candidates'][0]['content']['parts']
            as $part
        ) {

            if (
                isset($part['text']) &&
                is_string($part['text'])
            ) {

                $text .= $part['text'];
            }
        }
    }


    /*
     * =====================================================
     * 14. NO RESULT
     * =====================================================
     */

    if (trim($text) === '') {

        wp_send_json_error([

            'message' =>
            'Gemini returned no content.'

        ], 502);
    }


    /*
     * =====================================================
     * 15. CLEAN MARKDOWN CODE BLOCK
     * =====================================================
     */

    $text = trim($text);

    $text = preg_replace(
        '/^```(?:html)?\s*/i',
        '',
        $text
    );

    $text = preg_replace(
        '/\s*```$/',
        '',
        $text
    );

    $text = trim($text);


    /*
     * =====================================================
     * 16. ALLOW SAFE HTML
     * =====================================================
     */

    $html = wp_kses(

        $text,

        [

            'p' => [],

            'strong' => [],

            'b' => [],

            'em' => [],

            'i' => [],

            'br' => [],

            'ul' => [],

            'ol' => [],

            'li' => [],

            'h3' => [],

            'h4' => [],

            'span' => [

                'class' => true

            ]

        ]

    );


    /*
     * =====================================================
     * 17. RETURN TO JAVASCRIPT
     * =====================================================
     */

    wp_send_json_success([

        'html' => $html,

        'query' => $query

    ]);
}
// End Search GEMINI

